	@Test
	public void manyPlaceholderLikeIrisKeepTheirIdentity() throws IOException {
		StringBuilder record = new StringBuilder("{\"@id\":\"_:same\",\"urn:link\":[");
		for (int i = 0; i < 128; i++) {
			if (i > 0) {
				record.append(',');
			}
			record.append("{\"@id\":\"urn:rdf4j:ndjsonld:blank-node:").append(i).append(":0\"}");
		}
		record.append("],\"@type\":\"urn:rdf4j:ndjsonld:blank-node:128:0\"}\n");
		List<Statement> statements = new ArrayList<>();
		NDJSONLDParser parser = new NDJSONLDParser();
		parser.setRDFHandler(new AbstractRDFHandler() {
			@Override
			public void handleStatement(Statement statement) {
				statements.add(statement);
			}
		});
		parser.parse(new StringReader(record.toString()), "");
		assertEquals(129, statements.size());
		assertTrue(statements.stream().allMatch(s -> s.getSubject() instanceof BNode));
		for (int i = 0; i <= 128; i++) {
			String iri = "urn:rdf4j:ndjsonld:blank-node:" + i + ":0";
			assertTrue(statements.stream().anyMatch(s -> s.getObject().equals(vf.createIRI(iri))));
		}
	}

