	@Test
	public void contextArrayOverrideRemovesEarlierExplicitPrefix() throws IOException {
		String prefix = "{\"ex\":{\"@id\":\"urn:old\",\"@prefix\":true}}";
		String[] overrides = { "{\"ex\":null}", "{\"ex\":{\"@id\":\"urn:new\",\"@prefix\":false}}" };
		for (String override : overrides) {
			Map<String, String> namespaces = new HashMap<>();
			List<Statement> statements = new ArrayList<>();
			NDJSONLDParser parser = new NDJSONLDParser();
			parser.setRDFHandler(new AbstractRDFHandler() {
				@Override
				public void handleNamespace(String name, String uri) {
					namespaces.put(name, uri);
				}

				@Override
				public void handleStatement(Statement statement) {
					statements.add(statement);
				}
			});
			parser.parse(new StringReader("{\"@context\":[" + prefix + "," + override
					+ "],\"@id\":\"urn:s\",\"urn:p\":\"v\"}\n"), "");
			assertFalse(namespaces.containsKey("ex"));
			assertEquals(1, statements.size());
			assertEquals(vf.createIRI("urn:p"), statements.get(0).getPredicate());
		}
	}

