	@Test
	public void firstRecordReachesHandlerBeforeLaterInput() throws IOException {
		AtomicInteger statements = new AtomicInteger();
		String first = "{\"@id\":\"urn:first\",\"urn:p\":{\"@value\":\"one\"}}\n";
		String second = "{\"@id\":\"urn:second\",\"urn:p\":{\"@value\":\"two\"}}\n";
		Reader input = new Reader() {
			private int chunk;

			@Override
			public int read(char[] buffer, int offset, int length) {
				if (chunk == 0) {
					first.getChars(0, first.length(), buffer, offset);
					chunk++;
					return first.length();
				}
				if (statements.get() == 0) {
					throw new AssertionError("Requested a later record before delivering the first statement");
				}
				if (chunk == 1) {
					second.getChars(0, second.length(), buffer, offset);
					chunk++;
					return second.length();
				}
				return -1;
			}

			@Override
			public void close() {
			}
		};

		NDJSONLDParser parser = new NDJSONLDParser();
		parser.setRDFHandler(new AbstractRDFHandler() {
			@Override
			public void handleStatement(Statement statement) {
				statements.incrementAndGet();
			}
		});
		parser.parse(input, "");
		assertEquals(2, statements.get());
	}

	@Test
	public void recordsPreserveBlankNodesContextsAndNestedValues() throws IOException {
		String records = "{\"@context\":{\"ex\":{\"@id\":\"urn:\",\"@prefix\":true}},\"@id\":\"_:shared\","
				+ "\"ex:child\":{\"@id\":\"_:child\",\"ex:value\":{\"@value\":\"nested\"}}}\n"
				+ "{\"@context\":{\"ex\":{\"@id\":\"urn:\",\"@prefix\":true}},\"@id\":\"_:shared\",\"ex:other\":{\"@value\":\"later\"}}\n"
				+ "{\"@context\":{\"ex\":{\"@id\":\"urn:\",\"@prefix\":true}},\"ex:value\":{\"@value\":\"anon1\"}}\n"
				+ "{\"@context\":{\"ex\":{\"@id\":\"urn:\",\"@prefix\":true}},\"ex:value\":{\"@value\":\"anon2\"}}\n"
				+ "{\"@context\":{\"ex\":{\"@id\":\"urn:\",\"@prefix\":true}},\"@id\":\"urn:graph\","
				+ "\"@graph\":[{\"@id\":\"urn:graph-subject\",\"ex:value\":{\"@value\":\"graph\"}}]}\n";
		List<Statement> statements = new ArrayList<>();
		Map<String, String> namespaces = new HashMap<>();
		AtomicInteger starts = new AtomicInteger();
		AtomicInteger ends = new AtomicInteger();
		NDJSONLDParser parser = new NDJSONLDParser();
		parser.setRDFHandler(new AbstractRDFHandler() {
			@Override
			public void startRDF() {
				starts.incrementAndGet();
			}

			@Override
			public void handleNamespace(String prefix, String uri) {
				namespaces.put(prefix, uri);
			}

			@Override
			public void handleStatement(Statement statement) {
				statements.add(statement);
			}

			@Override
			public void endRDF() {
				ends.incrementAndGet();
			}
		});
		parser.parse(new StringReader(records), "");
		assertEquals(1, starts.get());
		assertEquals(1, ends.get());
		assertEquals("urn:", namespaces.get("ex"));
		assertEquals(6, statements.size());
		Statement link = statements.stream()
				.filter(s -> s.getPredicate().equals(vf.createIRI("urn:child")))
				.findFirst()
				.orElseThrow();
		Statement later = statements.stream()
				.filter(s -> s.getPredicate().equals(vf.createIRI("urn:other")))
				.findFirst()
				.orElseThrow();
		assertEquals(link.getSubject(), later.getSubject());
		assertInstanceOf(BNode.class, link.getSubject());
		Statement nested = statements.stream()
				.filter(s -> s.getObject().equals(vf.createLiteral("nested")))
				.findFirst()
				.orElseThrow();
		assertEquals(link.getObject(), nested.getSubject());
		Resource anonymous1 = statements.stream()
				.filter(s -> s.getObject().equals(vf.createLiteral("anon1")))
				.findFirst()
				.orElseThrow()
				.getSubject();
		Resource anonymous2 = statements.stream()
				.filter(s -> s.getObject().equals(vf.createLiteral("anon2")))
				.findFirst()
				.orElseThrow()
				.getSubject();
		assertNotEquals(anonymous1, anonymous2);
		assertNotEquals(anonymous1, link.getSubject());
		Statement graph = statements.stream()
				.filter(s -> s.getObject().equals(vf.createLiteral("graph")))
				.findFirst()
				.orElseThrow();
		assertEquals(vf.createIRI("urn:graph"), graph.getContext());
	}

